# %% [markdown]
# ## Step 6 — Hook Registry
#
# Hooks are a pub/sub system. The loop fires a topic, subscribers react in order.

# %%
from typing import Callable, Any

class HookRegistry:
    """Dispatch table for hook subscribers."""
    def __init__(self) -> None:
        self._subs: dict[str, list[Callable]] = {t: [] for t in HOOK_TOPICS}

    def on(self, topic: str, fn: Callable) -> None:
        if topic not in self._subs:
            raise ValueError(f"unknown hook topic: {topic}")
        self._subs[topic].append(fn)

    def fire(self, topic: str, payload: dict) -> list[Any]:
        results = []
        for fn in self._subs[topic]:
            results.append(fn(payload))
        return results

# Example: wire a telemetry hook
reg = HookRegistry()
log = []
reg.on("on_complete", lambda p: log.append(f"completed: {p['reason']}"))
reg.fire("on_complete", {"reason": "goal_met"})
print(f"Log: {log}")

# %% [markdown]
# ## Step 7 — Event & Session Result
#
# Every event is timestamped and typed. A **SessionResult** holds the final state, reason, plan steps, and event stream.

# %%
@dataclass
class Event:
    """Typed, timestamped event."""
    type: str
    payload: dict
    ts: float

    def to_dict(self) -> dict:
        return {"type": self.type, "payload": self.payload, "ts": self.ts}

@dataclass
class SessionResult:
    """Final result of a session."""
    state: State
    reason: str
    steps: list[Step]
    events: list[Event]

# Example event
evt = Event(type="session.start", payload={"goal": "ship release notes"}, ts=time.time())
