# %% [markdown]
# ## Step 9 — The Core Loop: State Machine & Transitions
#
# The harness is a deterministic state machine. **Every transition is validated**. This ensures the contract is enforceable.
#
# Key insight: The same event log can be replayed to reach the same state without re-calling the model.

# %%
class HarnessLoop:
    """Six-state deterministic loop with hooks and events."""

    def __init__(self, planner: Planner | None = None, budget: Budget | None = None) -> None:
        self.state: State = State.IDLE
        self.hooks = HookRegistry()
        self.budget = budget or Budget()
        self._planner = planner or _default_planner
        self._goal = ""
        self._plan: list[Step] = []
        self._cursor = 0
        self._events: list[Event] = []
        self._history: list[Step] = []
        self._reason = ""

    def _transition(self, target: State) -> None:
        """Validate and execute state transition."""
        legal: dict[State, set[State]] = {
            State.IDLE: {State.PLANNING},
            State.PLANNING: {State.EXECUTING, State.IDLE, State.DONE},
            State.EXECUTING: {State.AWAITING_TOOL, State.REFLECTING, State.IDLE},
            State.AWAITING_TOOL: {State.REFLECTING, State.IDLE},
            State.REFLECTING: {State.PLANNING, State.EXECUTING, State.DONE, State.IDLE},
            State.DONE: set(),
        }
        if target not in legal[self.state]:
            raise RuntimeError(f"illegal transition {self.state.value} -> {target.value}")
        self.state = target

    def _emit(self, etype: str, payload: dict) -> None:
        """Emit a typed event."""
        self._events.append(Event(type=etype, payload=payload, ts=time.time()))

loop = HarnessLoop()
print(f"Loop initialized. State: {loop.state.value}")

# %% [markdown]
# ## Step 10 — Budget Checking & Pull Points
#
# On every step, the loop checks if the budget is exceeded. If so, it yields control via a **pull request** — the caller decides whether to extend the budget and resume.

# %%
# Continue the HarnessLoop class (in same cell for clarity)

# Add the _check_budget and _pause methods to the loop.
# _check_budget returns None when within budget, else emits/ fires and hands
# back a PullRequest so the caller can decide whether to extend and resume.
def _harness_check_budget(self):
    which = self.budget.exceeded()
    if which is None:
        return None
    self._emit("budget.warn", {"limit": which})
    self.hooks.fire("on_budget_exceeded", {"limit": which, "budget": self.budget})
    return PullRequest(
        reason=f"budget_exceeded:{which}",
        state=State.IDLE,
        payload={"reason": f"budget_exceeded:{which}"},
    )

HarnessLoop._check_budget = _harness_check_budget

HarnessLoop._pause = lambda self, reason: (
    self._emit("session.pause", {"reason": reason}),
    self.hooks.fire("on_pause", {"reason": reason}),
    self._transition(State.IDLE),
    PullRequest(reason=reason, state=self.state, payload={"reason": reason})
)[-1]

print("✅ Budget checking and pause logic added")

# %% [markdown]
# ## Step 11 — Running the Loop
#
# Here's the core flow:
#
# 1. `run(goal)` → emits `session.start`, begins planning
# 2. Planner produces a draft → emits `plan.draft`, `plan.commit`
# 3. For each step:
#    - If no tool needed: execute in-place, emit `step.start`/`step.end`, continue
#    - If tool needed: yield control via `PullRequest`, emit `tool.call`
# 4. `resume(payload)` → feed tool result back, continue
# 5. Loop exits with `SessionResult` when done

# %%
# Implement run/resume on the HarnessLoop. The planner may be sync or async,
# so we await anything awaitable. run() and resume() share one driver, _advance(),
# which walks the plan from the cursor until it either yields a PullRequest
# (tool needed / budget exhausted) or finishes with a SessionResult.
import inspect


async def _harness_advance(self) -> "PullRequest | SessionResult":
    """Drive EXECUTING from the cursor; yield a PullRequest or finish (DONE)."""
    while self._cursor < len(self._plan):
        # Budget gate before each step (a pull point, not an exception).
        pr = self._check_budget()
        if pr is not None:
            return pr

        step = self._plan[self._cursor]
        self.budget.turns += 1
        self.hooks.fire("before_step", {"step": step})
        self._emit("step.start", {"id": step.id, "description": step.description})

        if step.requires_tool:
            # Yield control: emit tool.call, go AWAITING_TOOL, hand a PullRequest back.
            self.budget.tool_calls += 1
            self._emit("tool.call", {"id": step.id, "tool": step.tool_name, "args": step.tool_args})
            self.hooks.fire("before_tool_call", {"step": step})
            self._transition(State.AWAITING_TOOL)
            return PullRequest(
                reason=f"tool_call:{step.tool_name}",
                state=self.state,
                payload={"id": step.id, "tool": step.tool_name, "args": step.tool_args},
            )

        # No tool: execute in place and advance.
        step.result = f"done: {step.description}"
        self._emit("step.end", {"id": step.id})
        self.hooks.fire("after_step", {"step": step})
        self._history.append(step)
        self._cursor += 1

    # Plan exhausted -> reflect, then complete.
    self._transition(State.REFLECTING)
    self._reason = "goal_met"
    self._transition(State.DONE)
    self._emit("session.complete", {"reason": self._reason})
    self.hooks.fire("on_complete", {"reason": self._reason})
    return SessionResult(state=self.state, reason=self._reason, steps=self._history, events=self._events)


async def _harness_run(self, goal: str) -> "PullRequest | SessionResult":
    """Start a session: plan, then advance until a yield or completion."""
    self._goal = goal
    self._emit("session.start", {"goal": goal})
    self._transition(State.PLANNING)

    self.hooks.fire("before_plan", {"goal": goal})
    plan = self._planner(goal, self._history)
    if inspect.isawaitable(plan):
        plan = await plan
    self._plan = plan or []
    self._cursor = 0
    self._emit("plan.draft", {"steps": len(self._plan)})
    self.hooks.fire("after_plan", {"plan": self._plan})
    self._emit("plan.commit", {"steps": len(self._plan)})

    self._transition(State.EXECUTING)
    return await self._advance()


async def _harness_resume(self, payload: dict) -> "PullRequest | SessionResult":
    """Feed a tool result back in (AWAITING_TOOL -> REFLECTING -> EXECUTING) and continue."""
    if self.state is not State.AWAITING_TOOL:
        raise RuntimeError(f"resume() only valid in AWAITING_TOOL, not {self.state.value}")

    step = self._plan[self._cursor]
    if "error" in payload:
        step.error = payload["error"]
        self._emit("tool.error", {"id": step.id, "error": step.error})
    else:
        step.result = payload.get("result")
        self._emit("tool.result", {"id": step.id, "result": step.result})
    self.hooks.fire("after_tool_call", {"step": step})

    self._transition(State.REFLECTING)
    self._history.append(step)
    self._cursor += 1
    self._transition(State.EXECUTING)
    return await self._advance()


HarnessLoop._advance = _harness_advance
HarnessLoop.run = _harness_run
HarnessLoop.resume = _harness_resume

print("✅ run() / resume() / _advance() wired onto HarnessLoop")

# %% [markdown]
# ## Step 12 — Using LLM as a Planner
#
# Now the key insight: **the harness itself is model-agnostic**. We can wire any planner — including one that calls the LLM — into the loop.
#
# Here we create an **LLM-backed planner** that uses the LLM to generate steps for a goal.

# %%
async def llm_planner(goal: str, history: list[Step]) -> list[Step]:
    """Planner that calls the LLM to generate steps."""
    if history:
        return []  # Simplified: no replanning
    
    prompt = f"""You are a planning agent. Given a goal, respond with a JSON list of 2-3 steps.

Each step has:
- id (int, starting from 1)
- description (str)
- requires_tool (bool): true if the step needs external data/action
- tool_name (str or null): name of tool if required_tool is true
- tool_args (dict): arguments for the tool

Goal: {goal}

Respond with valid JSON only, no markdown or extra text."""
    
    r = await lrn_llm.call(
        [{"role": "user", "content": goal}],
        system=prompt,
        max_tokens=300
    )
    
    text = lrn_llm.text(r)
    print(f"LLM response:\n{text}")
    
    # Parse JSON response
    try:
        data = json.loads(text)
        steps = []
        for s in data if isinstance(data, list) else [data]:
            steps.append(Step(
                id=s.get("id", 1),
                description=s.get("description", ""),
                requires_tool=s.get("requires_tool", False),
                tool_name=s.get("tool_name"),
                tool_args=s.get("tool_args", {})
            ))
        return steps
    except (json.JSONDecodeError, KeyError) as e:
        print(f"Parse error: {e}")
        return []

print("✅ LLM planner defined")

