# ## Step 16 — Hook Subscriptions
#
# Hooks let operators intercept the loop. Here we wire multiple hooks to track execution.

# %%
# Demonstrate hooks with a new loop
async def demo_with_hooks():
    loop = HarnessLoop(planner=llm_planner, budget=Budget(max_turns=2, max_tool_calls=1))
    
    # Wire hooks
    hook_log = []
    
    def log_hook(topic):
        def fn(payload):
            hook_log.append((topic, payload))
        return fn
    
    loop.hooks.on("before_plan", log_hook("before_plan"))
    loop.hooks.on("after_plan", log_hook("after_plan"))
    loop.hooks.on("before_step", log_hook("before_step"))
    loop.hooks.on("on_complete", log_hook("on_complete"))
    
    result = await loop.run("Quick analysis")
    
    print(f"Hooks fired ({len(hook_log)}):")
    for topic, payload in hook_log:
        print(f"  {topic}")
    
    return loop

