async def try_it_yourself():
    """Your turn: customize the agent loop."""
    
    # Edit this goal
    goal = "Analyze Q3 sales data and recommend next quarter's strategy"
    
    # Create loop with LLM planner
    loop = HarnessLoop(planner=llm_planner, budget=Budget(max_turns=4, max_tool_calls=2))
    
    # Add your hook: log transitions
    transitions = []
    original_transition = loop._transition
    def logged_transition(target):
        transitions.append((loop.state.value, target.value))
        original_transition(target)
    loop._transition = logged_transition
    
    # Run the loop
    print(f"Goal: {goal}\n")
    result = await loop.run(goal)
    
    print(f"\nState transitions: {transitions}")
    print(f"Plan steps: {len(loop._plan)}")
    print(f"Result: {type(result).__name__}")
    
    return loop, result

my_loop, my_result = await try_it_yourself()
